UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent can write, delete, send, purchase or administer when most tasks only require reading or drafting.","customer_symptom":"A user or operator may observe the agent can write, delete, send, purchase or administer when most tasks only require reading or drafting; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the agent can write, delete, send, purchase or administer when most tasks only require reading or drafting, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"high","severity_rationale":"Excessive agent authority increases the impact of model error, prompt injection or compromise. Final severity depends on available actions, reachable assets, reversibility and external approval controls.","applicability":["tool-using agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between tool-using agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the agent can write, delete, send, purchase or administer when most tasks only require reading or drafting, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-053 tool catalogue, permission, credential-scope or agent-capability change","ARL-KB-053 new state-changing, destructive, financial or administrative action","ARL-KB-053 excessive-authority, unused-capability or privilege-abuse evidence","ARL-KB-053 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='e5b8d061f02047ccc03965fb8eb9008cba5dd1963cf27cf00cc8a10c9aaffd38', updated_at='2026-08-06' WHERE id='ARL-KB-053';
