until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-058 filesystem tool, path resolver, archive handler or sandbox-boundary change","ARL-KB-058 new file operation, mount, symlink or extraction capability","ARL-KB-058 traversal, link escape, race-condition or archive-breakout evidence","ARL-KB-058 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='025e5b00ba4f910174c983df5b17c59603f03cfcfa52507f0dac386692eede46', updated_at='2026-08-06' WHERE id='ARL-KB-058';
