idence.', limitations='This bounded ARL-KB-058 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='fd4b5c9184205cff4e58d42d7bb78a70923ec6338e7b6040bfcabb66dfc09af5', updated_at='2026-08-06' WHERE entry_id='ARL-KB-058';
