ible evidence.', limitations='This bounded ARL-KB-059 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='43b1a0e27b60b5d6d589f706c33e45256002041d3952fcd2f982b6110bdaf983', updated_at='2026-08-06' WHERE entry_id='ARL-KB-059';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of generated code executes without containment and make the remaining risk visible.', recommended_remediation='Use disposable sandboxes, no ambient secrets, blocked egress by default, strict resource limits, signed inputs and human approval for promotion.', default_owner='Sandbox platform owner', priority='P0', implementation_principles_json='["ARL-KB-059: Execute generated code in disposable least-privilege sandboxes rather than on the application host.","ARL-KB-059: Remove ambient secrets and deny network access by default unless explicitly required.","ARL-KB-059: Enforce strict CPU, memory, process, filesystem and execution-time limits and require governed promotion to production."]', monitoring='For ARL-KB-059, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Sandbox platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-059 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-059: “Generated code executes without containment” is no longer reproducible against the exact remediated version.","ARL-KB-059: Authorised in-scope use completes successfully, remains within the documented asset scope for generated code executes without containment, and produces no unintended side effect.","ARL-KB-059: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-059: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='3ef477ec12fdb73582ad6535c8856c9d0f7c124e0e9224a31f1dc5d0f20a6a2f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-059';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='788e44c69618d9363e07ed91743aa4a074c7c4b9e285669ef52350766ccffb29', updated_at='2026-08-06' WHERE entry_id='ARL-KB-059';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-059','critical','active','2026-10-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A malicious or replaced MCP server can advertise deceptive tools, steal context or return hostile instructions.","customer_symptom":"A user or operator may observe a malicious or replaced mcp server can advertise deceptive tools, steal context or return hostile instructions; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a malicious or replaced mcp server can advertise deceptive tools, steal context or return hostile instructions, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["MCP-enabled agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between MCP-enabled agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a malicious or replaced mcp server can advertise deceptive tools, steal context or return hostile instructions, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-060 MCP server identity, transport, package, version or deployment change","ARL-KB-060 tool catalogue, schema, credential or trust-policy change","ARL-KB-060 server replacement, provenance failure or unexpected catalogue-drift evidence","ARL-KB-060 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='f21ef447f50971edc2d4fe611b85d7a38b11bb75cb19bc0472dbdeeabbdb9a36', updated_at='2026-08-06' WHERE id='ARL-KB-060';
UPDATE risk_knowledge_checks SET objective='Determine whether each MCP server and advertised tool catalogue is attributable to an approved origin, version and transport identity and whether server replacement or catalogue drift is detected before use.', method='Verify MCP server origin, transport identity, package or deployment provenance, exact version or digest, tool catalogue digest and change history. In a controlled environment, simulate server replacement or an unexpected catalogue change and verify trust is denied or routed to explicit review before tool use.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-060 assessed system, version, environment and scope for MCP server identity and provenance are unverified","ARL-KB-060 control configuration or source location showing how reduce the likelihood and impact of mcp server identity and provenance are unverified and make the remaining risk visible.","ARL-KB-060 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-060 policy, authorization, tool or audit events proving whether the tested mcp server identity and provenance are unverified path executed","ARL-KB-060 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-060 passes only when “MCP server identity and provenance are unverified” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-060 fails when a malicious or replaced mcp server can advertise deceptive tools, steal context or return hostile instructions, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-060 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='117c1dc839e7ab444e43b93cc0b96c053564a55883b4f879057c7569b0182a9a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-060';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of mcp server identity and provenance are unverified and make the remaining risk visible.', recommended_remediation='Pin trusted MCP servers and versions, authenticate transport, review tool schemas, isolate credentials and require approval for catalogue changes.', default_owner='MCP platform owner', priority='P0', implementation_principles_json='["ARL-KB-060: Pin approved MCP server identities, versions or digests and authenticate transport.","ARL-KB-060: Treat tool-catalogue changes as security-relevant drift requiring review before use.","ARL-KB-060: Isolate server credentials and do not allow an MCP server''s text output to grant additional authority."]', monitoring='For ARL-KB-060, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the MCP platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-060 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-060: “MCP server identity and provenance are unverified” is no longer reproducible against the exact remediated version.","ARL-KB-060: Authorised in-scope use completes successfully, remains within the documented asset scope for mcp server identity and provenance are unverified, and produces no unintended side effect.","ARL-KB-060: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-060: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d3555354662bf67458bb5c1362fada07a77ba41cc28b8c6a9ee1a58e3c01926f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-060';
